.courses {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
  gap: 16px;
}
.course { min-width: 0; overflow-wrap: anywhere; }

.file-row { display: flex; align-items: center; gap: 12px; }
.filename {
  flex: 1; min-width: 0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.download { flex-shrink: 0; }

.action { background: #17735b; color: white; border: 1px solid #105c48; padding: 12px 16px; transition: background 120ms; }
.action:hover:not(:disabled) { background: #105c48; }
.action:focus-visible { outline: 3px solid #2259aa; outline-offset: 3px; }
.action:disabled { background: #e5e9e6; color: #59625b; border-color: #a8b2ab; cursor: not-allowed; }
@media (prefers-reduced-motion: reduce) { .action { transition: none; } }
